create unique index if not exists charges_fixed_utility_source_uq on public.charges(rental_relationship_id,source_type,source_id,period_start) where source_type='FIXED_UTILITY_CONFIG' and source_id is not null and period_start is not null;

create or replace function public.confirm_utility_bill(p_utility_bill_id uuid,p_manual_allocations jsonb default null) returns public.utility_bills language plpgsql security definer set search_path='' as $$ declare b public.utility_bills; c public.property_utility_configs; rel record; n int; i int:=0; allocated numeric:=0; each_amount numeric; item jsonb; target uuid; target_amount numeric; ch public.charges; total_weight int; begin select * into b from public.utility_bills where id=p_utility_bill_id for update; if not found then raise exception 'UTILITY_BILL_NOT_FOUND'; end if; if public.can_manage_administration(b.administration_id) is not true then raise exception 'MANAGEMENT_ACCESS_REQUIRED'; end if; if b.status<>'DRAFT' then raise exception 'UTILITY_BILL_NOT_DRAFT'; end if; select * into c from public.property_utility_configs where id=b.utility_config_id; if c.billing_mode<>'ACTUAL_BILL' then raise exception 'UTILITY_CONFIG_NOT_ACTUAL_BILL'; end if;
if c.distribution_method='MANUAL' then if p_manual_allocations is null or jsonb_typeof(p_manual_allocations)<>'array' then raise exception 'MANUAL_ALLOCATIONS_REQUIRED'; end if; for item in select value from jsonb_array_elements(p_manual_allocations) loop target:=(item->>'rental_relationship_id')::uuid; target_amount:=(item->>'amount')::numeric; if target_amount<0 then raise exception 'INVALID_ALLOCATION_AMOUNT'; end if; if not exists(select 1 from public.rental_relationships r join public.rental_relationship_subjects rs on rs.rental_relationship_id=r.id join public.rental_subjects s on s.id=rs.rental_subject_id join public.rooms rm on rm.id=s.room_id where r.id=target and r.administration_id=b.administration_id and r.status in('ACTIVE','ENDING','ENDED') and rm.property_id=b.property_id and r.real_start_date<=b.period_end and coalesce(r.actual_end_date,'infinity'::date)>=b.period_start) then raise exception 'RELATIONSHIP_NOT_IN_PROPERTY_PERIOD'; end if; insert into public.utility_allocations(administration_id,utility_bill_id,rental_relationship_id,amount) values(b.administration_id,b.id,target,target_amount); allocated:=allocated+target_amount; end loop; if allocated<>b.amount then raise exception 'ALLOCATIONS_MUST_EQUAL_BILL'; end if;
elsif c.distribution_method='BY_RESIDENT' then select coalesce(sum(x.residents),0)::int into total_weight from (select r.id,count(distinct rp.person_id)::int residents from public.rental_relationships r join public.rental_relationship_subjects rs on rs.rental_relationship_id=r.id join public.rental_subjects s on s.id=rs.rental_subject_id join public.rooms rm on rm.id=s.room_id join public.rental_participants rp on rp.rental_relationship_id=r.id and rp.participation_type in('TENANT','OCCUPANT') and coalesce(rp.starts_on,r.real_start_date)<=b.period_end and coalesce(rp.ends_on,r.actual_end_date,'infinity'::date)>=b.period_start where r.administration_id=b.administration_id and r.status in('ACTIVE','ENDING','ENDED') and rm.property_id=b.property_id and r.real_start_date<=b.period_end and coalesce(r.actual_end_date,'infinity'::date)>=b.period_start group by r.id) x; if total_weight=0 then raise exception 'NO_RESIDENTS_IN_BILL_PERIOD'; end if; n:=(select count(*) from (select r.id from public.rental_relationships r join public.rental_relationship_subjects rs on rs.rental_relationship_id=r.id join public.rental_subjects s on s.id=rs.rental_subject_id join public.rooms rm on rm.id=s.room_id join public.rental_participants rp on rp.rental_relationship_id=r.id and rp.participation_type in('TENANT','OCCUPANT') and coalesce(rp.starts_on,r.real_start_date)<=b.period_end and coalesce(rp.ends_on,r.actual_end_date,'infinity'::date)>=b.period_start where r.administration_id=b.administration_id and r.status in('ACTIVE','ENDING','ENDED') and rm.property_id=b.property_id and r.real_start_date<=b.period_end and coalesce(r.actual_end_date,'infinity'::date)>=b.period_start group by r.id) q); for rel in select r.id,count(distinct rp.person_id)::int residents from public.rental_relationships r join public.rental_relationship_subjects rs on rs.rental_relationship_id=r.id join public.rental_subjects s on s.id=rs.rental_subject_id join public.rooms rm on rm.id=s.room_id join public.rental_participants rp on rp.rental_relationship_id=r.id and rp.participation_type in('TENANT','OCCUPANT') and coalesce(rp.starts_on,r.real_start_date)<=b.period_end and coalesce(rp.ends_on,r.actual_end_date,'infinity'::date)>=b.period_start where r.administration_id=b.administration_id and r.status in('ACTIVE','ENDING','ENDED') and rm.property_id=b.property_id and r.real_start_date<=b.period_end and coalesce(r.actual_end_date,'infinity'::date)>=b.period_start group by r.id order by r.id loop i:=i+1; target_amount:=case when i=n then b.amount-allocated else round(b.amount*rel.residents/total_weight,2) end; insert into public.utility_allocations(administration_id,utility_bill_id,rental_relationship_id,amount) values(b.administration_id,b.id,rel.id,target_amount); allocated:=allocated+target_amount; end loop;
else select count(distinct r.id) into n from public.rental_relationships r join public.rental_relationship_subjects rs on rs.rental_relationship_id=r.id join public.rental_subjects s on s.id=rs.rental_subject_id join public.rooms rm on rm.id=s.room_id where r.administration_id=b.administration_id and r.status in('ACTIVE','ENDING','ENDED') and rm.property_id=b.property_id and r.real_start_date<=b.period_end and coalesce(r.actual_end_date,'infinity'::date)>=b.period_start; if n=0 then raise exception 'NO_ROOM_RENTALS_IN_BILL_PERIOD'; end if; each_amount:=round(b.amount/n,2); for rel in select distinct r.id from public.rental_relationships r join public.rental_relationship_subjects rs on rs.rental_relationship_id=r.id join public.rental_subjects s on s.id=rs.rental_subject_id join public.rooms rm on rm.id=s.room_id where r.administration_id=b.administration_id and r.status in('ACTIVE','ENDING','ENDED') and rm.property_id=b.property_id and r.real_start_date<=b.period_end and coalesce(r.actual_end_date,'infinity'::date)>=b.period_start order by r.id loop i:=i+1; target_amount:=case when i=n then b.amount-allocated else each_amount end; insert into public.utility_allocations(administration_id,utility_bill_id,rental_relationship_id,amount) values(b.administration_id,b.id,rel.id,target_amount); allocated:=allocated+target_amount; end loop; end if;
for rel in select * from public.utility_allocations where utility_bill_id=b.id loop insert into public.charges(administration_id,rental_relationship_id,charge_type,origin,description,period_start,period_end,due_date,amount,currency,source_type,source_id) values(b.administration_id,rel.rental_relationship_id,'UTILITY','UTILITY_ALLOCATION','Servicio público '||c.utility_code,b.period_start,b.period_end,coalesce(b.due_date,b.period_end),rel.amount,'COP','UTILITY_ALLOCATION',rel.id) returning * into ch; update public.utility_allocations set charge_id=ch.id where id=rel.id; end loop; update public.utility_bills set status='CHARGED',confirmed_at=now() where id=b.id returning * into b; return b; end $$;

create or replace function public.generate_fixed_utility_charges(p_relationship_id uuid,p_through_date date default current_date) returns setof public.charges language plpgsql security definer set search_path='' as $$ declare r public.rental_relationships; cfg record; v_month date; v_last_month date; v_due date; v_days int; created public.charges; begin select * into r from public.rental_relationships where id=p_relationship_id for update; if not found then raise exception 'RENTAL_RELATIONSHIP_NOT_FOUND'; end if; if public.can_manage_administration(r.administration_id) is not true then raise exception 'MANAGEMENT_ACCESS_REQUIRED'; end if; if r.status not in('ACTIVE','ENDING','ENDED') then raise exception 'RENTAL_NOT_CHARGEABLE'; end if; if r.tracking_start_date is null or r.payment_day is null then raise exception 'RENTAL_BILLING_CONFIGURATION_INCOMPLETE'; end if; if p_through_date<r.tracking_start_date then return; end if; for cfg in select distinct c.* from public.property_utility_configs c join public.rental_relationship_subjects rs on rs.rental_relationship_id=r.id join public.rental_subjects s on s.id=rs.rental_subject_id join public.rooms rm on rm.id=s.room_id where c.property_id=rm.property_id and c.administration_id=r.administration_id and c.billing_mode='FIXED' and c.is_enabled loop v_month:=date_trunc('month',r.tracking_start_date)::date; v_last_month:=date_trunc('month',least(p_through_date,coalesce(r.actual_end_date,p_through_date)))::date; while v_month<=v_last_month loop v_days:=extract(day from(v_month+interval '1 month'-interval '1 day'))::int; v_due:=v_month+(least(r.payment_day,v_days)-1); if v_due>=r.tracking_start_date then insert into public.charges(administration_id,rental_relationship_id,charge_type,origin,description,period_start,period_end,due_date,amount,currency,source_type,source_id) values(r.administration_id,r.id,'UTILITY','SYSTEM','Servicio fijo '||cfg.utility_code,greatest(v_month,r.tracking_start_date),least((v_month+interval '1 month'-interval '1 day')::date,coalesce(r.actual_end_date,'infinity'::date)),v_due,cfg.fixed_amount,'COP','FIXED_UTILITY_CONFIG',cfg.id) on conflict do nothing returning * into created; if found then return next created; end if; end if; v_month:=(v_month+interval '1 month')::date; end loop; end loop; return; end $$;
revoke all on function public.generate_fixed_utility_charges(uuid,date) from public,anon; grant execute on function public.generate_fixed_utility_charges(uuid,date) to authenticated,service_role;